def apply(doc: str, op: TextOp) -> str:
    if len(doc) != op.base_length:
        raise OTError(f"operation base length {op.base_length} != document length {len(doc)}")
    out, i = [], 0
    for c in op.ops:
        if is_retain(c):
            out.append(doc[i:i + c]); i += c
        elif is_insert(c):
            out.append(c)
        else:
            i -= c
    return "".join(out)

