def transform_index(op: TextOp, index: int) -> int:
    new_index = index
    for c in op.ops:
        if is_retain(c):
            index -= c
        elif is_insert(c):
            new_index += len(c)
        else:
            new_index -= min(index, -c)
            index += c
        if index < 0:
            break
    return new_index

