def diff_op(old: str, new: str) -> TextOp:
    p = 0
    while p < min(len(old), len(new)) and old[p] == new[p]:
        p += 1
    s = 0
    while s < min(len(old), len(new)) - p and old[-1 - s] == new[-1 - s]:
        s += 1
    return TextOp().retain(p).delete(len(old) - p - s).insert(new[p:len(new) - s]).retain(s)
